#include <stdio.h>

#define N 8

static void printArr(const char *tag, const int a[], int n)
{
    int i;
    printf("%s", tag);
    for (i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
}

/* 直接插入排序（稳定） */
static void insertSort(int a[], int n)
{
    int i, j;
    for (i = 1; i < n; i++) {
        if (a[i] < a[i - 1]) {
            int t = a[i];
            for (j = i - 1; j >= 0 && a[j] > t; j--)
                a[j + 1] = a[j];
            a[j + 1] = t;
        }
        printArr("insert pass: ", a, n);
    }
}

/* 冒泡排序（稳定，带提前结束标志） */
static void bubbleSort(int a[], int n)
{
    int i, j, exchanged;
    for (i = 0; i < n - 1; i++) {
        exchanged = 0;
        for (j = 0; j < n - 1 - i; j++)
            if (a[j] > a[j + 1]) {         /* 严格大于才交换 → 稳定 */
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                exchanged = 1;
            }
        printArr("bubble pass: ", a, n);
        if (!exchanged) break;
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int b[N];
    int i;

    for (i = 0; i < N; i++) b[i] = a[i];
    insertSort(a, N);
    bubbleSort(b, N);
    return 0;
}

#include <stdio.h>

#define N 8

/* 简单选择排序（不稳定），*swaps 统计交换次数 */
static void selectSort(int a[], int n, int *swaps)
{
    int i, j, k;
    *swaps = 0;
    for (i = 0; i < n - 1; i++) {
        k = i;
        for (j = i + 1; j < n; j++)
            if (a[j] < a[k]) k = j;
        if (k != i) {
            int t = a[i]; a[i] = a[k]; a[k] = t;
            (*swaps)++;
        }
        printf("pass %d: ", i + 1);
        for (j = 0; j < n; j++) printf("%d ", a[j]);
        printf("\n");
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int swaps = 0;

    selectSort(a, N, &swaps);
    printf("swaps=%d\n", swaps);
    return 0;
}

#include <stdio.h>

#define N 8

/* 直接插入排序：a[0] 作哨兵兼暂存，数据在 a[1..n] */
static void insertSort(int a[], int n)
{
    int i, j;
    for (i = 2; i <= n; i++) {
        if (a[i] < a[i - 1]) {
            a[0] = a[i];                 /* 暂存待插值 */
            for (j = i - 1; a[0] < a[j]; j--)
                a[j + 1] = a[j];         /* 后移 */
            a[j + 1] = a[0];             /* 插入到位 */
        }
        printf("pass %d: ", i - 1);
        for (j = 1; j <= n; j++) printf("%d ", a[j]);
        printf("\n");
    }
}

int main(void)
{
    int a[N + 1] = {0, 49, 38, 65, 97, 76, 13, 27, 49};

    insertSort(a, N);
    return 0;
}

#include <stdio.h>

#define N 8

/* 折半插入排序：折半找插入位置，再统一后移 */
static void binInsertSort(int a[], int n)
{
    int i, j, low, high, mid, t;
    for (i = 1; i < n; i++) {
        t = a[i];
        low = 0; high = i - 1;
        while (low <= high) {
            mid = (low + high) / 2;
            if (a[mid] > t) high = mid - 1;
            else            low  = mid + 1;
        }
        for (j = i - 1; j >= low; j--)
            a[j + 1] = a[j];
        a[low] = t;
    }
}

/* 希尔排序的一趟：对间隔 gap 的子序列做直接插入 */
static void shellPass(int a[], int n, int gap)
{
    int i, j;
    for (i = gap; i < n; i++) {
        if (a[i] < a[i - gap]) {
            int t = a[i];
            for (j = i - gap; j >= 0 && a[j] > t; j -= gap)
                a[j + gap] = a[j];
            a[j + gap] = t;
        }
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int b[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int gaps[3] = {4, 2, 1};
    int g, i;

    binInsertSort(a, N);
    printf("binInsert: ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");

    for (g = 0; g < 3; g++) {
        shellPass(b, N, gaps[g]);
        printf("gap=%d: ", gaps[g]);
        for (i = 0; i < N; i++) printf("%d ", b[i]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define N 8

/* 一趟划分：以 a[low] 为枢轴，返回枢轴最终位置 */
static int partition(int a[], int low, int high)
{
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot) high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot) low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

static void quickSort(int a[], int low, int high)
{
    if (low < high) {
        int p = partition(a, low, high);
        quickSort(a, low, p - 1);
        quickSort(a, p + 1, high);
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int i;
    quickSort(a, 0, N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* 自顶向下调整：使 a[s..m] 成为大根堆 */
static void heapAdjust(int a[], int s, int m)
{
    int j, t = a[s];
    for (j = 2 * s; j <= m; j *= 2) {
        if (j < m && a[j] < a[j + 1]) j++;   /* 取较大孩子 */
        if (t >= a[j]) break;                /* 已到位 */
        a[s] = a[j]; s = j;                  /* 继续下沉 */
    }
    a[s] = t;
}

/* 堆排序：a[1..n] 存数据 */
static void heapSort(int a[], int n)
{
    int i, t;
    for (i = n / 2; i >= 1; i--) heapAdjust(a, i, n);   /* 建初始堆 */
    for (i = n; i > 1; i--) {
        t = a[1]; a[1] = a[i]; a[i] = t;                /* 堆顶与末尾交换 */
        heapAdjust(a, 1, i - 1);                        /* 调整剩余 */
    }
}

int main(void)
{
    int a[N + 1] = {0, 49, 38, 65, 97, 76, 13, 27, 49};
    int i;
    heapSort(a, N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* 归并 [low..mid] 与 [mid+1..high] 两段有序序列到 tmp 再回写 */
static void merge(int a[], int tmp[], int low, int mid, int high)
{
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];   /* <= 保证稳定 */
        else              tmp[k++] = a[j++];
    }
    while (i <= mid)  tmp[k++] = a[i++];
    while (j <= high) tmp[k++] = a[j++];
    for (k = low; k <= high; k++) a[k] = tmp[k];
}

static void mergeSort(int a[], int tmp[], int low, int high)
{
    if (low < high) {
        int mid = (low + high) / 2;
        mergeSort(a, tmp, low, mid);
        mergeSort(a, tmp, mid + 1, high);
        merge(a, tmp, low, mid, high);
    }
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int tmp[N];
    int i;
    mergeSort(a, tmp, 0, N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 8

/* LSD 一趟：按 exp（1=个位,10=十位）做稳定的计数分配—收集 */
static void radixPass(int a[], int tmp[], int n, int exp)
{
    int count[10] = {0};
    int i, d;
    for (i = 0; i < n; i++) count[(a[i] / exp) % 10]++;
    for (i = 1; i < 10; i++) count[i] += count[i - 1];   /* 累积定位 */
    for (i = n - 1; i >= 0; i--) {                        /* 倒序保持稳定 */
        d = (a[i] / exp) % 10;
        tmp[--count[d]] = a[i];
    }
    for (i = 0; i < n; i++) a[i] = tmp[i];
}

int main(void)
{
    int a[N] = {49, 38, 65, 97, 76, 13, 27, 49};
    int tmp[N];
    int i;
    radixPass(a, tmp, N, 1);    /* 第一趟：个位 */
    printf("ones : ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    radixPass(a, tmp, N, 10);   /* 第二趟：十位 */
    printf("tens : ");
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

#define N 7

/* 无守卫版：比较 == INV + (n-1)，移动 == INV + 2(n-1)，两个都是精确等式 */
static void insertPlain(int *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;                       /* 存入哨兵 */
        for (j = i - 1; a[0] < a[j]; j--) {          /* ★ 不判 j >= 1，靠哨兵兜底 */
            (*cmp)++;
            a[j + 1] = a[j]; (*mv)++;                /* 后移 */
        }
        (*cmp)++;                                    /* 退出循环那次比较 */
        a[j + 1] = a[0]; (*mv)++;                    /* 写回 */
    }
}

/* 教材带守卫版：比较次数不变，移动次数少 2*(n-1-m) */
static void insertGuarded(int *a, int n, int *cmp, int *mv, int *inserted)
{
    int i, j;
    *cmp = 0; *mv = 0; *inserted = 0;
    for (i = 2; i <= n; i++) {
        (*cmp)++;
        if (a[i] < a[i - 1]) {
            (*inserted)++;
            a[0] = a[i]; (*mv)++;
            a[i] = a[i - 1]; (*mv)++;                /* 先把 a[i-1] 后移一位 */
            for (j = i - 2; a[0] < a[j]; j--) { (*cmp)++; a[j + 1] = a[j]; (*mv)++; }
            (*cmp)++;
            a[j + 1] = a[0]; (*mv)++;
        }
    }
}

/* 逆序对数：O(n^2) 暴力统计，作为独立于排序算法的第三方基准 */
static int inversions(const int *a, int n)
{
    int i, j, inv = 0;
    for (i = 1; i <= n; i++)
        for (j = i + 1; j <= n; j++)
            if (a[i] > a[j]) inv++;
    return inv;
}

static int sortedAsc(const int *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i] > a[i + 1]) return 0;
    return 1;
}

static void printArr(const int *a, int n)
{
    int i;
    for (i = 1; i <= n; i++) printf("%d%s", a[i], i < n ? " " : "");
}

/* 带标签的稳定性检查：key 相同则看 tag 是否仍按原次序 */
typedef struct { int key; int tag; } Rec;

static void insertRec(Rec *a, int n)
{
    int i, j;
    for (i = 2; i <= n; i++) {
        Rec tmp = a[i];
        for (j = i - 1; j >= 1 && tmp.key < a[j].key; j--)   /* ★ 严格小于 → 稳定 */
            a[j + 1] = a[j];
        a[j + 1] = tmp;
    }
}

int main(void)
{
    int base[3][N + 1] = {
        { 0, 13, 27, 38, 49, 65, 76, 97 },          /* 正序 */
        { 0, 49, 38, 65, 97, 76, 13, 27 },          /* 教材例 */
        { 0, 97, 76, 65, 49, 38, 27, 13 },          /* 逆序 */
    };
    const char *name[3] = { "正序", "随机", "逆序" };
    int a[N + 1], k, cmp, mv, gcmp, gmv, ins, inv, i;
    int plainCmp[3], plainMv[3];

    printf("== ① 三种输入下的比较/移动次数，并验证两个精确等式（n=%d）==\n", N);
    for (k = 0; k < 3; k++) {
        for (i = 0; i <= N; i++) a[i] = base[k][i];
        inv = inversions(a, N);
        insertPlain(a, N, &cmp, &mv);
        plainCmp[k] = cmp; plainMv[k] = mv;
        printf("  输入=%s ", name[k]);
        printArr(base[k], N);
        printf("\n    排序后 ");
        printArr(a, N);
        printf("  已升序=%d\n", sortedAsc(a, N));
        printf("    逆序对 INV=%d，无守卫版：比较 %d 次（INV+(n-1)=%d）相符=%d，移动 %d 次（INV+2(n-1)=%d）相符=%d\n",
               inv, cmp, inv + N - 1, cmp == inv + N - 1, mv, inv + 2 * (N - 1), mv == inv + 2 * (N - 1));

        for (i = 0; i <= N; i++) a[i] = base[k][i];
        insertGuarded(a, N, &gcmp, &gmv, &ins);
        printf("    带守卫版：比较 %d 次（与无守卫相同=%d），移动 %d 次，需要插入的趟数 m=%d，INV+2m=%d 相符=%d\n",
               gcmp, gcmp == cmp, gmv, ins, inv + 2 * ins, gmv == inv + 2 * ins);
    }

    printf("\n== ② 每趟结果（教材经典例 49 38 65 97 76 13 27）==\n");
    {
        int b[N + 1];
        for (i = 0; i <= N; i++) b[i] = base[1][i];
        printf("  初始  ");
        printArr(b, N);
        printf("\n");
        for (i = 2; i <= N; i++) {
            int j;
            b[0] = b[i];
            for (j = i - 1; j >= 1 && b[0] < b[j]; j--) b[j + 1] = b[j];
            b[j + 1] = b[0];
            printf("  第%d趟 ", i - 1);
            printArr(b, N);
            printf("\n");
        }
    }

    printf("\n== ③ 最好/最坏公式的验证（用①里实测出来的数）==\n");
    printf("  正序：实测比较 %d 次 == n-1 = %d ？%d；实测移动 %d 次 == 2(n-1) = %d ？%d\n",
           plainCmp[0], N - 1, plainCmp[0] == N - 1, plainMv[0], 2 * (N - 1), plainMv[0] == 2 * (N - 1));
    {
        int worst = (N - 1) * (N + 2) / 2, sum = 0, worstInv = N * (N - 1) / 2;
        for (i = 2; i <= N; i++) sum += i;
        printf("  逆序：实测比较 %d 次 == (n-1)(n+2)/2 = %d ？%d，也等于 Σ(i=2..n) i = %d 相符=%d\n",
               plainCmp[2], worst, plainCmp[2] == worst, sum, sum == worst);
        printf("  逆序的 INV = n(n-1)/2 = %d，与实测移动 %d 次满足 INV+2(n-1) = %d 相符=%d\n",
               worstInv, plainMv[2], worstInv + 2 * (N - 1), plainMv[2] == worstInv + 2 * (N - 1));
    }

    printf("\n== ④ 稳定性：两个 key=49 的记录 ==\n");
    {
        Rec r[5] = { { 0, 0 }, { 49, 1 }, { 38, 0 }, { 49, 2 }, { 27, 0 } };
        int p1 = 0, p2 = 0;
        printf("  排序前：");
        for (i = 1; i <= 4; i++) printf("%d(tag%d)%s", r[i].key, r[i].tag, i < 4 ? " " : "");
        insertRec(r, 4);
        printf("\n  排序后：");
        for (i = 1; i <= 4; i++) printf("%d(tag%d)%s", r[i].key, r[i].tag, i < 4 ? " " : "");
        for (i = 1; i <= 4; i++) { if (r[i].tag == 1) p1 = i; if (r[i].tag == 2) p2 = i; }
        printf("\n  ★ tag1 落在下标 %d、tag2 落在下标 %d → tag1 仍在 tag2 前面？%d（这就是「稳定」的定义）\n",
               p1, p2, p1 < p2);
        printf("    原因：内层用的是严格小于 a[0] < a[j]，遇到相等元素立即停止，新元素插到相等元素之后\n");
    }

    return 0;
}

#include <stdio.h>

#define N 7

static void insertPlain(int *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;
        for (j = i - 1; a[0] < a[j]; j--) { (*cmp)++; a[j + 1] = a[j]; (*mv)++; }
        (*cmp)++;
        a[j + 1] = a[0]; (*mv)++;
    }
}

static void insertGuarded(int *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        (*cmp)++;
        if (a[i] < a[i - 1]) {
            a[0] = a[i]; (*mv)++;
            a[i] = a[i - 1]; (*mv)++;
            for (j = i - 2; a[0] < a[j]; j--) { (*cmp)++; a[j + 1] = a[j]; (*mv)++; }
            (*cmp)++;
            a[j + 1] = a[0]; (*mv)++;
        }
    }
}

/* 折半插入。trace 记下每趟的比较次数与插入位置，便于逐趟核对 */
static void insertBinary(int *a, int n, int *cmp, int *mv, int *perCmp, int *perPos)
{
    int i, j, low, high, mid;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;
        low = 1; high = i - 1;
        perCmp[i] = 0;
        while (low <= high) {
            mid = low + (high - low) / 2;
            perCmp[i]++;
            (*cmp)++;
            if (a[0] >= a[mid]) low = mid + 1;      /* ★ >= 保证稳定 */
            else high = mid - 1;
        }
        for (j = i - 1; j >= low; j--) { a[j + 1] = a[j]; (*mv)++; }
        a[low] = a[0]; (*mv)++;
        perPos[i] = low;
    }
}

static int inversions(const int *a, int n)
{
    int i, j, inv = 0;
    for (i = 1; i <= n; i++)
        for (j = i + 1; j <= n; j++)
            if (a[i] > a[j]) inv++;
    return inv;
}

static int sameArr(const int *a, const int *b, int n)
{
    int i;
    for (i = 1; i <= n; i++) if (a[i] != b[i]) return 0;
    return 1;
}

static void printArr(const int *a, int n)
{
    int i;
    for (i = 1; i <= n; i++) printf("%d%s", a[i], i < n ? " " : "");
}

int main(void)
{
    int base[3][N + 1] = {
        { 0, 13, 27, 38, 49, 65, 76, 97 },
        { 0, 49, 38, 65, 97, 76, 13, 27 },
        { 0, 97, 76, 65, 49, 38, 27, 13 },
    };
    const char *name[3] = { "正序", "随机", "逆序" };
    int a[N + 1], b[N + 1], g[N + 1], k, i;
    int pc, pm, bc, bm, gc, gm, inv, perCmp[N + 1], perPos[N + 1];
    int binCmp[3], plainCmp[3];

    printf("== ① 三种输入下，直接插入 vs 折半插入（n=%d）==\n", N);
    for (k = 0; k < 3; k++) {
        for (i = 0; i <= N; i++) { a[i] = base[k][i]; b[i] = base[k][i]; g[i] = base[k][i]; }
        inv = inversions(a, N);
        insertPlain(a, N, &pc, &pm);
        insertBinary(b, N, &bc, &bm, perCmp, perPos);
        insertGuarded(g, N, &gc, &gm);
        binCmp[k] = bc;
        plainCmp[k] = pc;
        printf("  输入=%s ", name[k]);
        printArr(base[k], N);
        printf("  INV=%d\n", inv);
        printf("    直接插入(无守卫)：比较 %d 次，移动 %d 次\n", pc, pm);
        printf("    直接插入(带守卫)：比较 %d 次，移动 %d 次\n", gc, gm);
        printf("    折半插入        ：比较 %d 次，移动 %d 次\n", bc, bm);
        printf("    三者结果相同=%d；折半与无守卫的移动次数相同=%d（都是 INV+2(n-1)=%d）\n",
               sameArr(a, b, N) && sameArr(a, g, N), bm == pm, inv + 2 * (N - 1));
    }
    printf("  ★ 折半插入的比较次数在三种输入下是 %d / %d / %d，最大差 %d 次（几乎与初始状态无关）\n",
           binCmp[0], binCmp[1], binCmp[2],
           (binCmp[0] > binCmp[2] ? binCmp[0] - binCmp[2] : binCmp[2] - binCmp[0]));
    printf("  ★ 直接插入的比较次数是 %d / %d / %d，最大差 %d 次（完全由 INV 决定）\n",
           plainCmp[0], plainCmp[1], plainCmp[2], plainCmp[2] - plainCmp[0]);

    printf("\n== ② 逐趟折半定位过程（随机输入 49 38 65 97 76 13 27）==\n");
    for (i = 0; i <= N; i++) b[i] = base[1][i];
    insertBinary(b, N, &bc, &bm, perCmp, perPos);
    printf("  趟数 i / 有序段长度 i-1 / 折半比较次数 / 定位到的插入位置\n");
    for (i = 2; i <= N; i++)
        printf("  i=%d  长度=%d  折半比较=%d  插入位置=%d\n", i, i - 1, perCmp[i], perPos[i]);
    printf("  合计折半比较 = %d 次（这就是①里随机输入的折半比较次数？%d）\n", bc, bc == binCmp[1]);
    {
        int sumLog = 0, t, c;
        for (i = 2; i <= N; i++) {
            c = 0;
            for (t = 1; t < i; t *= 2) c++;      /* c = ceil(log2 i) */
            sumLog += c;
        }
        printf("  理论上界 Σ(i=2..n) ceil(log2 i) = %d，实测 %d，不超过上界？%d\n", sumLog, bc, bc <= sumLog);
        printf("  同一输入下直接插入比较 %d 次、折半插入比较 %d 次，省了 %d 次\n",
               plainCmp[1], bc, plainCmp[1] - bc);
    }

    printf("\n== ③ 正序输入时的反例：折半插入反而更贵 ==\n");
    for (i = 0; i <= N; i++) { a[i] = base[0][i]; b[i] = base[0][i]; }
    insertGuarded(a, N, &gc, &gm);
    insertBinary(b, N, &bc, &bm, perCmp, perPos);
    printf("  带守卫直接插入：比较 %d 次，移动 %d 次（正序时一次都不用动）\n", gc, gm);
    printf("  折半插入      ：比较 %d 次，移动 %d 次（照样要查找、存哨兵、写回）\n", bc, bm);
    printf("  ★ 折半插入在最好情况下更贵？%d\n", bc + bm > gc + gm);

    return 0;
}

#include <stdio.h>

#define MAX 128

typedef struct { int key; int tag; } Rec;

static void printTagged(const Rec *a, int n)
{
    int i;
    for (i = 1; i <= n; i++) {
        printf("%d", a[i].key);
        if (a[i].tag > 0) printf("(%c)", 'a' + a[i].tag - 1);
        if (i < n) printf(" ");
    }
}

static int inversionsRec(const Rec *a, int n)
{
    int i, j, inv = 0;
    for (i = 1; i <= n; i++)
        for (j = i + 1; j <= n; j++)
            if (a[i].key > a[j].key) inv++;
    return inv;
}

/* 直接插入（带守卫），统计比较与移动 */
static void insertGuarded(Rec *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        (*cmp)++;
        if (a[i].key < a[i - 1].key) {
            Rec t = a[i];
            (*mv)++;
            a[i] = a[i - 1]; (*mv)++;
            for (j = i - 2; j >= 1 && t.key < a[j].key; j--) { (*cmp)++; a[j + 1] = a[j]; (*mv)++; }
            (*cmp)++;
            a[j + 1] = t; (*mv)++;
        }
    }
}

/* 希尔排序的一轮：增量 d。verbose 为真时打印本轮结束后的序列 */
static void shellPass(Rec *a, int n, int d, int *cmp, int *mv, int verbose, const char *label)
{
    int i, j;
    for (i = d + 1; i <= n; i++) {
        (*cmp)++;
        if (a[i].key < a[i - d].key) {
            Rec t = a[i];
            (*mv)++;
            a[i] = a[i - d]; (*mv)++;
            for (j = i - d; j >= 1 && t.key < a[j].key; j -= d) {   /* ★ 必须判 j >= 1 */
                (*cmp)++;
                a[j + d] = a[j]; (*mv)++;
            }
            (*cmp)++;
            a[j + d] = t; (*mv)++;
        }
    }
    if (verbose) {
        printf("  %s d=%d 之后：", label, d);
        printTagged(a, n);
        printf("   （逆序对 %d）\n", inversionsRec(a, n));
    }
}

/* 按给定增量序列做完整个希尔排序 */
static void shellSort(Rec *a, int n, const int *inc, int incLen, int *cmp, int *mv, int verbose)
{
    int k;
    *cmp = 0; *mv = 0;
    for (k = 0; k < incLen; k++) {
        char label[24];
        if (verbose) sprintf(label, "第%d轮", k + 1);
        else label[0] = '\0';
        shellPass(a, n, inc[k], cmp, mv, verbose, label);
    }
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i].key > a[i + 1].key) return 0;
    return 1;
}

/* 确定性伪随机（LCG），保证每次运行输出一致 */
static unsigned long long rngState;
static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned)bound);
}

int main(void)
{
